# ---------------------------------------------------------------- story key lookup
def skey(title):
    t = title.lower().replace('’', "'")
    rules = [
        ('parambak', 'parambak'), ('cafsd graduands', 'cafsd'), ('plants 250 mangrove', 'mangrove250'),
        ('green wall program', 'greenwall'), ('nstw', 'nstw'), ("president's farm field day", 'fieldday'),
        ('photo contest', 'photocontest'), ('graduation tree planting', 'gradcont'),
        ('research greenhouse', 'greenhouse'), ("1,068-hectare", 'forest'),
        ('conserving ilocos indigenous', 'ifp'), ('nature-based solutions for mangrove', 'nbs25'),
        ('rotary club', 'rotary'), ('a new bambusetum', 'bambusetum'),
        ('indigenous food plants propagated', 'ifpgarden'), ('mangrove nature-based solutions project runs', 'nbscont'),
        ('bambusetums create', 'bambusetums'), ('biodiversity conservation learning center', 'bclc'),
        ('trains coastal towns', 'mangtrain'), ('farmers in sarrat', 'alukon'), ('siwawer', 'siwawer'),
        ('community foodscapes as learning', 'foodscape'), ('school-on-the-air', 'soa'),
        ('bamboo propagation and plantation', 'pinili'), ('vermicast', 'vermicast'),
        ('onion farmers trained', 'onion'), ('science high school', 'pshs'), ('soil health research', 'soil'),
        ('rice paddy art', 'paddy'), ('talon', 'talon'), ('kalbario', 'kpnp'),
        ('land use policy commits', 'sirmata_land'), ('from vanishing plants', 'ifp_vanishing'),
        ('sirmata 2040: planning', 'sirmata_plan'), ('tmp foundation, denr', 'pasuquin'),
        ('and denr region 1', 'denr'), ('foodscapes established with vintar', 'foodscape_vintar'),
        ('groundwater quality', 'groundwater'), ('memorandum no. 26-370', 'memo26370'),
        ('water policy protects', 'waterpolicy'), ('regional ecology center', 'embcommit'),
        ('clean-up drive', 'cleanup'), ('policies eliminate styrofoam', 'iwmp'),
        ('own tumblers', 'tumbler'), ('hazardous waste disposal under', 'ipwmp'),
    ]
    for k, v in rules:
        if k in t:
            return v
    raise KeyError(title)

